<?php

declare(strict_types=1);

namespace App\Policies;

use App\Models\Module;
use Illuminate\Auth\Access\HandlesAuthorization;
use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Filament Shield policy for Module. Generated by `php artisan shield:generate`;
 * each ability maps to a "{Action}:Module" permission seeded by RoleSeeder.
 * super_admin bypasses these checks (Gate::before in Shield).
 *
 * Regenerating policies with shield:generate may overwrite these docblocks.
 */
class ModulePolicy
{
    use HandlesAuthorization;

    /**
     * Determine whether the admin may list Module records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ViewAny:Module" permission.
     */
    public function viewAny(AuthUser $authUser): bool
    {
        return $authUser->can('ViewAny:Module');
    }

    /**
     * Determine whether the admin may view one Module record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Module  $module  The record being authorized.
     * @return bool True when the admin holds the "View:Module" permission.
     */
    public function view(AuthUser $authUser, Module $module): bool
    {
        return $authUser->can('View:Module');
    }

    /**
     * Determine whether the admin may create Module records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Create:Module" permission.
     */
    public function create(AuthUser $authUser): bool
    {
        return $authUser->can('Create:Module');
    }

    /**
     * Determine whether the admin may edit a Module record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Module  $module  The record being authorized.
     * @return bool True when the admin holds the "Update:Module" permission.
     */
    public function update(AuthUser $authUser, Module $module): bool
    {
        return $authUser->can('Update:Module');
    }

    /**
     * Determine whether the admin may delete one Module record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Module  $module  The record being authorized.
     * @return bool True when the admin holds the "Delete:Module" permission.
     */
    public function delete(AuthUser $authUser, Module $module): bool
    {
        return $authUser->can('Delete:Module');
    }

    /**
     * Determine whether the admin may bulk delete Module records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "DeleteAny:Module" permission.
     */
    public function deleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('DeleteAny:Module');
    }

    /**
     * Determine whether the admin may restore one soft-deleted Module record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Module  $module  The record being authorized.
     * @return bool True when the admin holds the "Restore:Module" permission.
     */
    public function restore(AuthUser $authUser, Module $module): bool
    {
        return $authUser->can('Restore:Module');
    }

    /**
     * Determine whether the admin may permanently delete one Module record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Module  $module  The record being authorized.
     * @return bool True when the admin holds the "ForceDelete:Module" permission.
     */
    public function forceDelete(AuthUser $authUser, Module $module): bool
    {
        return $authUser->can('ForceDelete:Module');
    }

    /**
     * Determine whether the admin may permanently bulk delete Module records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ForceDeleteAny:Module" permission.
     */
    public function forceDeleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('ForceDeleteAny:Module');
    }

    /**
     * Determine whether the admin may bulk restore soft-deleted Module records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "RestoreAny:Module" permission.
     */
    public function restoreAny(AuthUser $authUser): bool
    {
        return $authUser->can('RestoreAny:Module');
    }

    /**
     * Determine whether the admin may duplicate a Module record.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Module  $module  The record being authorized.
     * @return bool True when the admin holds the "Replicate:Module" permission.
     */
    public function replicate(AuthUser $authUser, Module $module): bool
    {
        return $authUser->can('Replicate:Module');
    }

    /**
     * Determine whether the admin may reorder Module records.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Reorder:Module" permission.
     */
    public function reorder(AuthUser $authUser): bool
    {
        return $authUser->can('Reorder:Module');
    }
}
